        private int tail = 0;

        private int read() {
            if (head >= tail) {
                try {
                    tail = in.read(buffer, 0, buffer.length);
                } catch (IOException e) {
                    tail = -1;
                }
                head = 0;
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public long nextLong() {
            int c = read();
            while (c <= 32 && c != -1) {
                c = read();
